/// <summary>
/// MPJ_5046_MetpayInterfaces 05/05/2021
/// Service class to run the update and creation of new record
/// </summary>
public class METVendOpenItemsAckService extends SysOperationServiceBase
{
    str                                     errorMessage;
    str                                     infologMessage;
}

Method.Source:
    /// <summary>
    /// MPJ_5046_MetpayInterfaces 05/05/2021
    /// Checks if run in batch or not.
    /// </summary>
    /// <param name = "_dataContract">Data contract</param>
    public void processOperation(METVendOpenItemsAckContract _dataContract)
    {
        VendTrans                               vendTrans;
        METVendOpenItems                        metVendOpenItems, delVendOpenItems;
        int                                     num;  
        

        try
        {   
            ttsbegin;
            while select crosscompany metVendOpenItems
                where metVendOpenItems.AckStatus == METAckStatus::Rejected
                      && metVendOpenItems.RecordStatus == METRecordStatus::New
                join vendTrans
                    where metVendOpenItems.VendTransOpenRecId == vendTrans.RecId
                                  
            {
                vendTrans.selectForUpdate(true);
                vendTrans.Approved =  NoYes::No;
                vendTrans.ReleaseDateComment = metVendOpenItems.ResponseCodeDesc;                
                vendTrans.update();

                metVendOpenItems.selectForUpdate(true);
                metVendOpenItems.RecordStatus = METRecordStatus::Processed;
                metVendOpenItems.update();

                num = date2num(DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone())) - date2num(DateTimeUtil::date(metVendOpenItems.ModifiedDateTime));
                delete_from delVendOpenItems 
                    where delVendOpenItems.RecordStatus == METRecordStatus::Processed
                    && num == _dataContract.getNumOfDays();
            }
            ttscommit;            
        }
        catch(Exception::CLRError)
        {
            //If an error occurs, check if log header is available
            this.getInfologMessage();
            System.Exception ex = CLRInterop::getLastException();
            errorMessage += ex.Message + ex.ToString();
            if (metVendOpenItems)
            {
                this.updateLogLine(errorMessage, infologMessage, metVendOpenItems);
            }
            info(errorMessage + infologMessage);
            info ("@MET:VendCrossDocFeeErrorHandler");

        }

    }

    /// <summary>
    /// MPJ_5046_MetpayInterfaces 05/05/2021
    /// This method gets the info of the error into a variable
    /// </summary>
    private void getInfologMessage()
    {
        SysInfologEnumerator sysInfologEnumerator;
        SysInfologMessageStruct sysInfologMessageStruct;

        sysInfologEnumerator = SysInfologEnumerator::newData(infolog.infologData());

        while (sysInfologEnumerator.moveNext())
        {
            sysInfologMessageStruct = new SysInfologMessageStruct(sysInfologEnumerator.currentMessage());

            if (sysInfologEnumerator.currentException() == Exception::Error)
            {
                errorMessage += strfmt(sysInfologMessageStruct.message());
            }
            infologMessage += strfmt(sysInfologMessageStruct.message());
        }
    }

    /// <summary>
    /// MPJ_5046_MetpayInterfaces 05/05/2021
    /// This method updates the error field in the table
    /// </summary>
    /// <param name = "_mbsErrorMsg">error message</param>
    /// <param name = "_mbsInfologMsg">info log</param>
    /// <param name = "_metVendOpenItems">METVendOpenItems table</param>
    private void updateLogLine(str _mbsErrorMsg, str _mbsInfologMsg, METVendOpenItems _metVendOpenItems)
    {
        ttsbegin;

        // if log header is available use the global variable to update the current log line to the below
        // status
        _metVendOpenItems.selectForUpdate(true);
        _metVendOpenItems.Error = _mbsErrorMsg + _mbsInfologMsg;
        _metVendOpenItems.update();

        ttscommit;
    }
